"use client"

import { Clock, Users, MapPin } from "lucide-react"
import { Button } from "@/components/ui/button"
import type { Event } from "@/lib/events-data"

interface EventCardProps {
  event: Event
  onDetailsClick: (event: Event) => void
}

export function EventCard({ event, onDetailsClick }: EventCardProps) {
  const getDuration = () => {
    return "1 день"
  }

  const getLevel = () => {
    const attendancePercent = Math.round((event.currentAttendees / event.maxAttendees) * 100)
    if (attendancePercent >= 90) return "Популярное"
    if (attendancePercent >= 70) return "Востребованное"
    return "Доступное"
  }

  return (
    <div
      className="group relative aspect-[3/4] rounded-2xl overflow-hidden cursor-pointer"
      onClick={() => onDetailsClick(event)}
    >
      {/* Background Image */}
      <img
        src={event.image || "/placeholder.svg"}
        alt={event.title}
        className="absolute inset-0 w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
      />

      {/* Dark Gradient Overlay */}
      <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-black/20" />

      {/* Content */}
      <div className="absolute inset-0 flex flex-col justify-end p-5">
        {/* Title */}
        <h3 className="text-white text-xl font-bold mb-3 line-clamp-2">
          {event.title}
        </h3>

        {/* Info Items */}
        <div className="space-y-1.5 text-white/90 text-sm mb-4">
          <div className="flex items-center gap-2">
            <Clock className="w-4 h-4 text-white/70" />
            <span>{getDuration()}</span>
          </div>
          <div className="flex items-center gap-2">
            <Users className="w-4 h-4 text-white/70" />
            <span>{getLevel()}</span>
          </div>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <MapPin className="w-4 h-4 text-white/70" />
              <span className="truncate max-w-[120px]">{event.location}</span>
            </div>
            <span className="font-semibold text-white">
              {event.isFree ? "Бесплатно" : `${event.price.toLocaleString()} руб.`}
            </span>
          </div>
        </div>

        {/* Button */}
        <Button
          variant="outline"
          className="w-full bg-transparent border-white/30 text-white hover:bg-white hover:text-black transition-all duration-300"
          onClick={(e) => {
            e.stopPropagation()
            onDetailsClick(event)
          }}
        >
          Узнать подробнее
        </Button>
      </div>
    </div>
  )
}
